<?php
use SwimlogStandalone\StructuredWorkouts as SW;
use SwimLogEvaluation\Structured_Workout_Export as SE;
use SwimLogEvaluation\Structured_Workout_FIT as SF;
$base=SW::url();
?>
<section class="calendar-panel workout-page structured-page" aria-labelledby="structures-title"><div class="workout-page-heading"><h2 id="structures-title"><?php echo isset($structureForm)?($structureForm['id']==='new'?'Add Structured Workout':'Edit Structured Workout'):(isset($structureDetail)?'Structured Workout':'Structured Workouts'); ?></h2><a class="control" href="<?php echo esc_url($base); ?>">List Structured Workouts</a><?php if(!isset($structureForm)): ?><a class="control" href="<?php echo esc_url(SW::url('new',true)); ?>">Add Structured Workout</a><?php endif; ?></div>
<?php if(isset($_GET['structure_saved'])): ?><p class="save-notice" role="status">Structured workout updated.</p><?php endif; ?>
<?php if(isset($structureError)): ?><p role="alert"><?php echo esc_html($structureError->get_error_message()); ?></p>
<?php elseif(isset($structureForm)): $f=$structureForm; ?>
<?php if($f['error']): ?><p role="alert"><?php echo esc_html($f['error']->get_error_message()); ?></p><?php endif; ?>
<form class="structure-editor" method="post" action="/?action=structured_write" id="swimlog-structure-form">
<?php foreach(array('structure_id'=>$f['id'],'operation'=>'save','nonce'=>wp_create_nonce('standalone_structure_save_'.$f['id']),'revision'=>$f['revision'])as$key=>$value): ?><input type="hidden" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($value); ?>"><?php endforeach; ?>
<div class="plan-field"><label for="structure-title">Workout title</label><input id="structure-title" name="title" maxlength="191" required value="<?php echo esc_attr($f['title']); ?>"></div>
<noscript><p>Enable JavaScript to edit workout sections and steps. Your existing prescription is retained.</p></noscript>
<?php if(is_array($f['document'])&&isset($f['document']['sections'])&&is_array($f['document']['sections'])): ?><div id="swimlog-structure-editor" data-document="<?php echo esc_attr(wp_json_encode($f['document'])); ?>"></div><?php else: ?><p>The submitted definition could not be opened in the editor. <a href="<?php echo esc_url(SW::url($f['id'],true)); ?>">Reload the editor</a> to recover the last saved prescription.</p><?php endif; ?><input type="hidden" id="swimlog-structure-document" name="document" value="<?php echo esc_attr($f['raw_document']??wp_json_encode($f['document'])); ?>">
<div class="plan-actions"><button>Save structured workout</button><a class="control" href="<?php echo esc_url($f['id']==='new'?$base:SW::url($f['id'])); ?>">Cancel</a></div></form><script src="/?action=structured_asset&amp;kind=js" defer></script>
<?php elseif(isset($structureDetail)): $d=$structureDetail;$text=SE::text($d['title'],$d['document']); ?>
<h3><?php echo esc_html($d['title']); ?></h3>
<?php if($d['locked']): ?><p role="status">This prescription is locked because it has recorded-swim history. Duplicate it to edit a new copy.</p><?php endif; ?>
<?php if($d['hidden']): ?><p>Hidden from the active library.</p><?php endif; ?>
<div class="plan-actions"><?php if(!$d['locked']): ?><a class="control" href="<?php echo esc_url(SW::url($d['id'],true)); ?>">Edit structured workout</a><?php endif; ?>
<?php foreach(array('duplicate'=>'Duplicate workout',($d['hidden']?'unhide':'hide')=>($d['hidden']?'Unhide workout':'Hide workout'))as$op=>$label): $id=$d['id'];require __DIR__.'/structured-action.php';endforeach; ?></div>
<?php if(is_wp_error($text)): ?><p role="alert"><?php echo esc_html($text->get_error_message()); ?></p><?php else: ?><pre class="swimlog-prescription-preview"><?php echo esc_html($text); ?></pre>
<div class="plan-actions"><?php foreach(array('txt'=>'Download text','fit'=>'Download FIT','pdf'=>'Download PDF')as$format=>$label): ?><a class="control" download="<?php echo esc_attr('swim-workout-'.$d['id'].'.'.$format); ?>" href="<?php echo esc_url('/?action=structured_download&id='.$d['id'].'&format='.$format.'&nonce='.wp_create_nonce('standalone_structure_export_'.$d['id'].'_'.$format)); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></div>
<details><summary>FORM text — copy and paste</summary><p>Copy this prescription into FORM and review its interpretation before saving.</p><textarea class="form-prescription" rows="12" readonly aria-label="FORM prescription text"><?php echo esc_textarea($text); ?></textarea></details>
<?php $compiled=SF::compile($d['document']);if(is_wp_error($compiled)): ?><p><?php echo esc_html($compiled->get_error_message()); ?></p><?php else: foreach($compiled['warnings']as$warning): ?><p><?php echo esc_html($warning); ?></p><?php endforeach;endif; ?>
<p>FIT downloads are planned workout prescriptions, not recorded activities. TrainingPeaks planned-library imports may require another supported format.</p><?php endif; ?>
<section class="structure-links"><h3>Planned workout</h3>
<?php if($d['unavailable_link']): ?><p>This prescription has an unavailable planned-workout link. Review it in WordPress tools.</p>
<?php elseif($d['plan']): ?><p><a href="<?php echo esc_url('/?date='.$d['plan']['date'].'&plan='.$d['plan']['id']); ?>"><?php echo esc_html($d['plan']['date'].' · '.$d['plan']['title']); ?></a></p><?php if(!$d['locked']): $id=$d['id'];$op='unlink';$label='Unlink planned workout';require __DIR__.'/structured-action.php';endif; ?>
<?php elseif(!$d['locked']): $targets=SW::targets($owner);if(!$targets): ?><p>No unassigned swimming plans are available. <a href="/?edit_plan=new">Plan a workout</a>, then return here to link it.</p><?php else: ?>
<form method="post" action="/?action=structured_write" class="structure-link-form"><?php foreach(array('structure_id'=>$d['id'],'operation'=>'link','nonce'=>wp_create_nonce('standalone_structure_link_'.$d['id']),'revision'=>$d['revision'])as$key=>$value): ?><input type="hidden" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($value); ?>"><?php endforeach; ?><label for="structure-plan">Choose an unassigned planned swim</label><select id="structure-plan" name="plan_token" required><option value="">Choose a plan</option><?php foreach($targets as$target): ?><option value="<?php echo esc_attr($target['id'].':'.$target['revision']); ?>"><?php echo esc_html($target['label']); ?></option><?php endforeach; ?></select><button>Link planned workout</button></form><p>Linking leaves the plan’s written instructions and recorded history unchanged.</p><?php endif;endif; ?></section>
<?php if(!$d['history']): ?><details class="structure-delete"><summary>Delete unused workout</summary><?php $id=$d['id'];$op='delete';$label='Delete permanently';require __DIR__.'/structured-action.php'; ?></details><?php else: ?><p>This workout has historical references and cannot be deleted. You can hide it.</p><?php endif; ?>
<?php else: $list=$structureLibrary;if(is_wp_error($list)): ?><p role="alert"><?php echo esc_html($list->get_error_message()); ?></p><?php else: ?>
<nav class="event-filters" aria-label="Structured workout visibility"><?php foreach(array('active'=>'Active','hidden'=>'Hidden','all'=>'All')as$key=>$label): ?><a class="control" <?php if($list['filter']===$key)echo 'aria-current="page"'; ?> href="<?php echo esc_url($base.'&visibility='.$key); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav><p>Page <?php echo esc_html($list['page'].' of '.$list['pages']); ?> · <?php echo esc_html($list['count']); ?> workouts in this view. The plugin library returns at most its 500 most recently modified workouts.</p>
<?php if(!$list['rows']): ?><p>No structured workouts in this view.</p><?php endif; ?><div class="event-list"><?php foreach($list['rows']as$row): ?><article class="event-list-card"><h3><a href="<?php echo esc_url(SW::url($row['id'])); ?>"><?php echo esc_html($row['title']); ?></a></h3><p><?php echo esc_html($row['distance']); ?></p></article><?php endforeach; ?></div><nav class="event-filters" aria-label="Structured workout pages"><?php if($list['page']>1): ?><a class="control" href="<?php echo esc_url($base.'&visibility='.$list['filter'].'&structure_page='.($list['page']-1)); ?>">Previous page</a><?php endif;if($list['page']<$list['pages']): ?><a class="control" href="<?php echo esc_url($base.'&visibility='.$list['filter'].'&structure_page='.($list['page']+1)); ?>">Next page</a><?php endif; ?></nav>
<?php endif;endif; ?></section>
